  const lat = (b.lat - a.lat) * radians;
  const lng = (b.lng - a.lng) * radians;
  const value = Math.sin(lat / 2) ** 2 + Math.cos(a.lat * radians) * Math.cos(b.lat * radians) * Math.sin(lng / 2) ** 2;
