  const config = JSON.parse(result.output);
  const oldLine = `    "template": ${JSON.stringify(config.prompt.template)}`;
  const newLine = `    "template": ${JSON.stringify(`${gate}\n\n${config.prompt.template}`)}`;
  patch += `*** Update File: /Users/lizziesiegle/Desktop/demos3idkman/sf-stairs-map/${path}\n@@\n-${oldLine}\n+${newLine}\n`;
}
patch += "*** End Patch";
const r = await tools.apply_patch(patch);
text(typeof r === "string" ? r : JSON.stringify(r));

