}
function fit() {
  const points = visible.filter(s=>s.lat!==null && s.lng!==null).map(s=>L.latLng(s.lat!, s.lng!));
  if(points.length)map.fitBounds(L.latLngBounds(points), {padding: [45,45], maxZoom: 16, animate: false});
