const files = [
  ["trail-confidence.json", "Slop gate: Treat generic AI filler, invented claims or precision, placeholder functionality, duplicated controls, and user-facing behavior described but not implemented as quality failures. Base the assessment on concrete diff evidence; do not invent findings. Lower confidence when these failures are present."],
  ["trail-drift.json", "Slop gate: Treat generic AI filler, invented claims or precision, placeholder functionality, duplicated controls, and user-facing behavior described but not implemented as drift from a focused product. Base the assessment on concrete diff evidence; do not invent findings."],
  ["trail-review-focus.json", "Slop gate: Treat generic AI filler, invented claims or precision, placeholder functionality, duplicated controls, and user-facing behavior described but not implemented as defects only when the diff provides a concrete, actionable user-facing failure. Do not create taste-based or speculative comments."],
  ["trail-review.json", "Slop gate: Treat generic AI filler, invented claims or precision, placeholder functionality, duplicated controls, and user-facing behavior described but not implemented as defects only when the diff provides a concrete, actionable user-facing failure. Do not create taste-based or speculative comments."],
  ["trail-risk.json", "Slop gate: Treat generic AI filler, invented claims or precision, placeholder functionality, duplicated controls, and user-facing behavior described but not implemented as concrete product risk. Base the assessment on concrete diff evidence; do not invent findings."],
  ["trail-security.json", "Slop gate: Treat generic AI filler, invented claims or precision, placeholder functionality, duplicated controls, and user-facing behavior described but not implemented as evidence to investigate only when it creates a concrete security-relevant failure. Do not score subjective copy or visual taste as security risk."],
  ["trail-summary.json", "Slop gate: Do not use generic AI filler, invented claims or precision, or describe behavior the diff does not implement. State only concrete, user-visible changes supported by the diff."]
];
let patch = "*** Begin Patch\n";
for (const [file, gate] of files) {
  const path = `.entire/runners/${file}`;
  const result = await tools.exec_command({cmd:`jq -c . ${path}`,workdir:"/Users/lizziesiegle/Desktop/demos3idkman/sf-stairs-map",yield_time_ms:10000,max_output_tokens:3000});
  const config = JSON.parse(result.output);
  const next = config.prompt.template.startsWith("Slop gate:") ? config.prompt.template : `${gate}\n\n${config.prompt.template}`;
  patch += `*** Update File: /Users/lizziesiegle/Desktop/demos3idkman/sf-stairs-map/${path}\n@@\n-    "template": ${JSON.stringify(config.prompt.template)}\n+    "template": ${JSON.stringify(next)}\n`;
}
patch += "*** End Patch";
const r = await tools.apply_patch(patch);
text(typeof r === "string" ? r : JSON.stringify(r));

